--
-- Name: refunds; Type: TABLE; Schema: public; Owner: pakkatrip
--

CREATE TABLE public.refunds (
    id bigint NOT NULL,
    amount numeric(12,2) NOT NULL,
    refund_pct numeric(5,2) NOT NULL,
    fee_refunded boolean NOT NULL,
    initiated_by character varying(10) NOT NULL,
    reason text NOT NULL,
    status character varying(12) NOT NULL,
    processed_at timestamp with time zone,
    created_at timestamp with time zone NOT NULL,
    booking_id bigint NOT NULL,
    payment_id bigint NOT NULL,
    failure_reason character varying(200) NOT NULL,
    gateway_refund_id character varying(64),
    CONSTRAINT refund_amount_non_negative CHECK ((amount >= (0)::numeric))
);


ALTER TABLE public.refunds OWNER TO pakkatrip;

