-- Name: refunds_id_seq; Type: SEQUENCE; Schema: public; Owner: pakkatrip
--

ALTER TABLE public.refunds ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY (
    SEQUENCE NAME public.refunds_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);


--
-- Name: reviews; Type: TABLE; Schema: public; Owner: pakkatrip
--

CREATE TABLE public.reviews (
    id bigint NOT NULL,
    reviewer_name character varying(100) NOT NULL,
    rating smallint NOT NULL,
    comment text NOT NULL,
    operator_reply text NOT NULL,
    replied_at timestamp with time zone,
    is_published boolean NOT NULL,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    booking_id bigint NOT NULL,
    operator_id bigint NOT NULL,
    package_id bigint NOT NULL,
    user_id bigint,
    CONSTRAINT rating_1_5 CHECK (((rating >= 1) AND (rating <= 5))),
    CONSTRAINT reviews_rating_check CHECK ((rating >= 0))
);


ALTER TABLE public.reviews OWNER TO pakkatrip;

