COPY public.package_itinerary_days (id, day_number, title, description, package_id) FROM stdin;
49	1	Delhi → Manali (overnight Volvo)	Board the AC Volvo at Majnu ka Tilla at 7:30 PM. Overnight journey via Chandigarh and Mandi with a dinner halt at Murthal.	69
50	2	Solang Valley & Old Manali	Reach Manali by 9 AM and check in. Afternoon at Solang Valley (paragliding and ropeway at own cost). Evening walk through Old Manali's cafés.	69
51	3	Hadimba Temple → Delhi	Visit Hadimba Devi Temple, Vashisht hot springs and Mall Road. Board the return Volvo at 5 PM; reach Delhi early next morning.	69
52	1	Delhi → Shivpuri riverside camp	Leave Delhi at 5:30 AM and reach the Shivpuri camp by noon. Lunch, beach volleyball, then a bonfire with music and dinner by the Ganga.	70
53	2	16 km rafting & Ganga Aarti → Delhi	Breakfast, then 16 km of white-water rafting from Shivpuri to Rishikesh. Laxman Jhula, Triveni Ghat evening aarti, and back in Delhi by 11 PM.	70
54	1	Delhi → Bhuntar (overnight Volvo)	Board at 6:30 PM for the overnight drive into the Parvati Valley.	71
55	2	Kasol → Kheerganga trek	Taxi to Barshaini and a 12 km trek through pine forest to Kheerganga. Soak in the hot spring and camp under the stars.	71
56	3	Descent, Manikaran → Delhi	Trek down after breakfast, stop at Manikaran Sahib, and board the evening Volvo to Delhi.	71
57	1	Delhi → Udaipur (overnight sleeper)	Board the AC sleeper at 6 PM for the overnight run to the City of Lakes.	72
58	2	City Palace & Lake Pichola	Check in to the haveli, explore City Palace, take a sunset boat ride on Lake Pichola and watch the Bagore ki Haveli folk dance show.	72
59	3	Saheliyon ki Bari → Delhi	Morning at Saheliyon ki Bari and Fateh Sagar Lake, shopping at Hathi Pol, and the evening bus back to Delhi.	72
60	1	Delhi → Shimla	Early departure, breakfast stop at Murthal, reach Shimla by afternoon. Walk the Ridge, Christ Church and Mall Road.	73
61	2	Kufri & Green Valley → Delhi	Morning excursion to Kufri and Green Valley viewpoints, then head back to Delhi by night.	73
62	1	Lucknow → Varanasi	Reach Varanasi by noon, darshan at Kashi Vishwanath, and the grand Ganga Aarti at Dashashwamedh Ghat.	74
63	2	Sunrise boat ride & Sarnath → Lucknow	Dawn boat ride along the ghats, breakfast, a visit to Sarnath, and back to Lucknow by evening.	74
64	1	Delhi → Corbett resort	Reach the resort by lunch. Pool time, an evening nature walk along the Kosi river, and a bonfire dinner.	75
65	2	Jeep safari → Delhi	Early morning jeep safari in the Jhirna zone, breakfast, a stop at Corbett Falls, and back to Delhi by night.	75
66	1	Mumbai → Goa (overnight sleeper)	Board at Dadar at 7 PM for the coastal overnight drive.	76
67	2	North Goa beaches	Check in, then Baga, Calangute and Fort Aguada. Evening free for the shacks.	76
68	3	Old Goa & river cruise	Basilica of Bom Jesus, Se Cathedral, Panjim's Latin Quarter and a sunset Mandovi river cruise.	76
69	4	Anjuna → Mumbai	Anjuna flea market and Vagator cliffs, then the evening bus back to Mumbai.	76
70	1	Delhi → Mussoorie	Drive via Dehradun, stop at Kempty Falls, and spend the evening on Mall Road.	77
71	2	Gun Hill & Company Garden → Delhi	Gun Hill ropeway, Company Garden, a café breakfast, and back to Delhi by night.	77
72	1	Delhi → Guptkashi	Long scenic drive via Rishikesh and Rudraprayag.	78
73	2	Gaurikund → Kedarnath	16 km trek (pony or palki at own cost) to Kedarnath; evening aarti at the temple.	78
74	3	Darshan & descent	Early morning darshan, then trek back down to Gaurikund and drive to Guptkashi.	78
75	4	Guptkashi → Delhi	Drive back to Delhi, reaching by late night.	78
76	1	Delhi → Shimla (overnight)	Overnight Volvo to Shimla.	79
77	2	Shimla → Sangla	A dramatic drive along the Sutlej to the Sangla valley.	79
78	3	Chitkul — the last village	Day trip to Chitkul near the Tibet border, then Kamru Fort.	79
79	4	Sangla → Delhi	Drive back to Shimla and board the overnight Volvo to Delhi.	79
80	1	Delhi → Jaipur	Reach by noon. Amber Fort, Panna Meena ka Kund, and a Rajasthani dinner at Chokhi Dhani.	80
81	2	Hawa Mahal & City Palace → Delhi	Hawa Mahal, City Palace, Jantar Mantar and shopping at Johari Bazaar, then back to Delhi.	80
82	1	Delhi → Dharamshala (overnight Volvo)	Board at 8 PM; reach McLeodganj by morning.	81
83	2	McLeodganj & Bhagsu	Dalai Lama Temple, Bhagsu waterfall and Tibetan cafés.	81
84	3	Dharamshala → Delhi	HPCA cricket stadium, Norbulingka Institute, and the evening Volvo back.	81
85	1	Delhi → Manali (overnight Volvo)	Board at 6 PM; reach Manali by morning.	82
86	2	Atal Tunnel & Sissu	Drive through the Atal Tunnel to the Sissu snow point (cab at own cost); Club House in the evening.	82
87	3	Manali local → Delhi	Hadimba Temple, Tibetan monastery, Mall Road, and the evening Volvo back.	82
88	1	Delhi → Manali (overnight)	Overnight Volvo to Manali.	83
89	2	Solang & Atal Tunnel	Solang Valley and the Atal Tunnel north portal.	83
90	3	Manali → Kasol	Drive to the Parvati Valley, visit Manikaran Sahib, and spend the evening by the river in Kasol.	83
91	4	Kasol → Delhi	Chalal village walk, then the evening Volvo to Delhi.	83
92	1	Delhi → Pushkar camp	Reach Pushkar, camel safari and a folk night.	84
93	2	Brahma Temple → Delhi	Brahma Temple and the lake ghats, then back to Delhi.	84
94	1	Mumbai → Goa (overnight sleeper)	Board at 7 PM for South Goa.	85
95	2	Dudhsagar jeep safari	Jeep safari to Dudhsagar Falls and lunch at a spice plantation.	85
96	3	Palolem & Colva → Mumbai	Palolem beach and Colva sunset, then the night bus back.	85
